  typeof(MainWindow).GetMethod("Page",F).Invoke(main,new object[]{"Автодеплой"});Pump();All<ComboBox>(main).Single(c=>c.Name=="deployRecipe").SelectedIndex=2;Pump();All<TextBox>(main).Single(t=>t.Name=="deployVkCall").Text=String.Join("\n",Calls());Pump();main.UpdateLayout();Check(All<TextBox>(main).Count(t=>t.Name=="deployVkCall")==6,"actual SWG form splits six pasted links");var callScroll=All<ScrollViewer>(main).Single(t=>t.Name=="deployVkCallsScroll");Check(callScroll.ScrollableHeight>0&&callScroll.ViewportHeight>=96,"six-call list scrolls in compact form");Check(main.OwnedWindows.Count==0,"manual input never opens VK authentication");Save(main,"swg-six-manual-fields");
  string output;using(var process=Process.Start(new ProcessStartInfo(args[1],"-X utf8 \""+Path.GetFullPath(args[2])+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8})){var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(15000)){process.Kill();throw new TimeoutException();}output=stdout.GetAwaiter().GetResult();Check(process.ExitCode==0,"provision fixtures including six calls pass");}
