  int index=0;foreach(string link in links){var profile=DeploymentConnection.Read(link);Check(!String.IsNullOrEmpty(profile.Secret),profile.Protocol+" secret present in connection details");if(profile.Protocol=="openflux")Check(profile.Secret=="fixture-secret-key-1234567890","OpenFlux actual encryption key decoded without installing engine");File.WriteAllBytes(Path.Combine(root,"qr-"+index+".png"),ConnectionQr.Png(link));File.WriteAllText(Path.Combine(root,"qr-"+index+".txt"),link,new UTF8Encoding(false));var popup=(Window)typeof(MainWindow).GetMethod("ConnectionPopup",F).Invoke(main,new object[]{profile});popup.ShowActivated=false;popup.WindowStartupLocation=WindowStartupLocation.Manual;popup.Left=popup.Top=-10000;popup.Show();Pump();popup.UpdateLayout();Check(All<TextBox>(popup).Single(t=>t.Name=="connectionShareText").Text==link,profile.Protocol+" popup contains complete import link");Check(All<TextBox>(popup).Single(t=>t.Name=="connectionSecretText").Text==profile.Secret,profile.Protocol+" popup contains actual key");Check(All<Image>(popup).Single(i=>i.Name=="connectionQr").Source!=null,profile.Protocol+" QR visible");foreach(var field in All<FrameworkElement>(popup).Where(e=>e is TextBox||e is Image)){var bounds=field.TransformToAncestor(popup).TransformBounds(new Rect(0,0,field.ActualWidth,field.ActualHeight));Check(bounds.Left>=0&&bounds.Right<=popup.ActualWidth+1&&bounds.Bottom<=popup.ActualHeight+1,profile.Protocol+" popup fields fit minimum window");}if(profile.Calls.Length==6)Check(All<TextBox>(popup).Single(t=>t.Name=="connectionVkCalls").Text.Split('\n').Length==6,"six bound calls shown in popup");Save(popup,"popup-"+profile.Protocol+"-"+index);popup.Close();Pump();index++;}
