ectionsSection");section.BringIntoView();Pump();main.UpdateLayout();Save(main,"deployment-connection-results");main.Close();Wait(()=>!main.IsVisible);app.Shutdown();Console.WriteLine("OK "+checks+" deployment sharing and manual VK checks");return 0;
